    strings = []
    costs = []
    for _ in range(N):
        s = input[idx]
        c = int(input[idx+1])
        strings.append(s)
        costs.append(c)
        idx += 2

    min_cost = float('inf')

    # Check single strings
    for i in range(N):
        if is_palindrome(strings[i]):
            if costs[i] < min_cost:
                min_cost = costs[i]

    # Check pairs
    for i in range(N):
        for j in range(N):
            s1 = strings[i]
            s2 = strings[j]
            combined1 = s1 + s2
            if is_palindrome(combined1):
                total = costs[i] + costs[j]
                if total < min_cost:
                    min_cost = total
            combined2 = s2 + s1
            if is_palindrome(combined2):
                total = costs[i] + costs[j]
                if total < min_cost:
                    min_cost = total

    # Check triplets
    for i in range(N):
        for j in range(N):
            for k in range(N):
                s1 = strings[i]
                s2 = strings[j]
                s3 = strings[k]
                for perm in permutations([s1, s2, s3]):
                    combined = ''.join(perm)
                    if is_palindrome(combined):
                        total = costs[i] + costs[j] + costs[k]
                        if total < min_cost:
                            min_cost = total

    if min_cost == float('inf'):
        print(-1)
    else:
        print(min_cost)

