import sys
from collections import deque

def main():
    input = sys.stdin.read().split()
    idx = 0
    N = int(input[idx])
    idx += 1
    strings = []
    for _ in range(N):
        s = input[idx]
        c = int(input[idx + 1])
        strings.append((s, c))
        idx += 2

    max_length = 200
    dp = dict()
    queue = deque()

    for s, c in strings:
        if s not in dp or c < dp[s]:
            dp[s] = c
            queue.append(s)

    while queue:
        current = queue.popleft()
        for s, c in strings:
            new_s = current + s
            if len(new_s) > max_length:
                continue
            new_cost = dp[current] + c
            if new_s not in dp or new_cost < dp[new_s]:
                dp[new_s] = new_cost
                queue.append(new_s)

    min_cost = float('inf')

    # Check for single palindrome strings
    for s in dp:
        if s == s[::-1]:
            if dp[s] < min_cost:
                min_cost = dp[s]

    # Check for pairs of strings s and reverse(s)
    for s in dp:
        rev_s = s[::-1]
        if rev_s in dp:
            total_cost = dp[s] + dp[rev_s]
            if total_cost < min_cost:
                min_cost = total_cost

    if min_cost == float('inf'):
        print(-1)
    else:
        print(min_cost)

