    min_cost = float('inf')

    # Check single strings
    for i in range(N):
        if is_palindrome(strings[i]):
            if costs[i] < min_cost:
                min_cost = costs[i]

    # Check pairs
    for i in range(N):
        for j in range(N):
            s1 = strings[i]
            s2 = strings[j]
            combined1 = s1 + s2
            combined2 = s2 + s1
            if is_palindrome(combined1) or is_palindrome(combined2):
                total_cost = costs[i] + costs[j]
                if total_cost < min_cost:
                    min_cost = total_cost

    # Check triplets
    for i in range(N):
        for j in range(N):
            for k in range(N):
                s_list = [strings[i], strings[j], strings[k]]
                for perm in permutations(s_list):
                    combined = ''.join(perm)
                    if is_palindrome(combined):
                        total_cost = costs[i] + costs[j] + costs[k]
                        if total_cost < min_cost:
                            min_cost = total_cost

