from functools import lru_cache

MOD = 10**9 + 7

def main():
    n, k = map(int, sys.stdin.readline().split())

    @lru_cache(maxsize=None)
    def dp(mask, sum_so_far):
        if sum_so_far > k:
            return 0
        if mask == (1 << n) - 1:
            return 1 if sum_so_far == k else 0
        total = 0
        pos = bin(mask).count('1') + 1
        for j in range(1, n+1):
            if not (mask & (1 << (j-1))):
                contribution = abs(pos - j)
                total += dp(mask | (1 << (j-1)), sum_so_far + contribution)
                total %= MOD
        return total

    print(dp(0, 0))

