def main():
    import sys
    input = sys.stdin.read
    n, k = map(int, input().split())

    if k % 2 != 0:
        print(0)
        return

    from collections import defaultdict

    # dp is a dictionary where keys are masks and values are dictionaries of sum to count
    dp = defaultdict(lambda: defaultdict(int))
    dp[0][0] = 1

    for mask in range(1 << n):
        for s in list(dp[mask].keys()):
            count = dp[mask][s]
            # Determine the next element to assign
            num_elements = bin(mask).count('1')
            next_element = num_elements + 1
            for pos in range(1, n+1):
                if not (mask & (1 << (pos - 1))):
                    contribution = abs(pos - next_element)
                    new_mask = mask | (1 << (pos - 1))
                    new_s = s + contribution
                    if new_s > k:
                        continue
                    dp[new_mask][new_s] = (dp[new_mask][new_s] + count) % MOD

    full_mask = (1 << n) - 1
    print(dp[full_mask].get(k, 0) % MOD)

