        dist[u] = 0
        heap = [(0, u)]
        while heap:
            current_dist, node = heapq.heappop(heap)
            if current_dist > dist[node]:
                continue
            for v, w in adj[node]:
                if dist[v] > dist[node] + w:
                    dist[v] = dist[node] + w
                    heapq.heappush(heap, (dist[v], v))
        for v in range(1, N + 1):
            dist_matrix[u][v] = dist[v]

    count = 0
