from functools import lru_cache

def main():
    N, K = map(int, sys.stdin.readline().split())
    A = list(map(int, sys.stdin.readline().split()))

    max_bit = 40
    cnt_ones = [0] * (max_bit + 1)
    for j in range(max_bit + 1):
        cnt = 0
        for a in A:
            if (a >> j) & 1:
                cnt += 1
        cnt_ones[j] = cnt

    @lru_cache(maxsize=None)
    def dp(pos, tight):
        if pos < 0:
            return 0
        max_contribution = 0
        if tight:
            current_k_bit = (K >> pos) & 1
            for b in [0, 1]:
                if b > current_k_bit:
                    continue
                contribution = 0
                if b == 0:
                    contribution = cnt_ones[pos] * (1 << pos)
                else:
                    contribution = (N - cnt_ones[pos]) * (1 << pos)
                new_tight = tight and (b == current_k_bit)
                res = contribution + dp(pos - 1, new_tight)
                if res > max_contribution:
                    max_contribution = res
        else:
            for b in [0, 1]:
                contribution = 0
                if b == 0:
                    contribution = cnt_ones[pos] * (1 << pos)
                else:
                    contribution = (N - cnt_ones[pos]) * (1 << pos)
                res = contribution + dp(pos - 1, False)
                if res > max_contribution:
                    max_contribution = res
        return max_contribution

    result = dp(max_bit, True)
    print(result)

