    for a in A:
        for j in range(41):
            if (a >> j) & 1:
                cnt_ones[j] += 1

    # Initialize DP
    prev_tight = 0
    prev_not_tight = -float('inf')

    for j in reversed(range(41)):
        current_bit = (K >> j) & 1
        contrib_0 = cnt_ones[j] * (1 << j)
