        new_tight = -float('inf')
        new_not_tight = -float('inf')

        # Process previous tight state
        if prev_tight != -float('inf'):
            for choice in [0, 1]:
                if choice > current_bit:
                    continue
                if choice == 0:
                    contrib = contrib_0
                else:
                    contrib = contrib_1
                if choice < current_bit:
                    if new_not_tight < prev_tight + contrib:
                        new_not_tight = prev_tight + contrib
                else:
                    if new_tight < prev_tight + contrib:
                        new_tight = prev_tight + contrib

        # Process previous not tight state
        if prev_not_tight != -float('inf'):
            for choice in [0, 1]:
                contrib = contrib_0 if choice == 0 else contrib_1
                if new_not_tight < prev_not_tight + contrib:
                    new_not_tight = prev_not_tight + contrib

        # Update for next iteration
        prev_tight, prev_not_tight = new_tight, new_not_tight

