MOD = 998244353

def main():
    N, K = map(int, sys.stdin.readline().split())
    matrix = [list(map(int, sys.stdin.readline().split())) for _ in range(N)]

    def can_swap_rows(i, j):
        for col in range(N):
            if matrix[i][col] + matrix[j][col] > K:
                return False
        return True

    def can_swap_cols(x, y):
        for row in range(N):
            if matrix[row][x] + matrix[row][y] > K:
                return False
        return True

    visited_rows = [False] * N
    row_components = []
    for i in range(N):
        if not visited_rows[i]:
            q = deque()
            q.append(i)
            visited_rows[i] = True
            size = 0
            while q:
                node = q.popleft()
                size += 1
                for j in range(N):
                    if not visited_rows[j] and can_swap_rows(node, j):
                        visited_rows[j] = True
                        q.append(j)
            row_components.append(size)

    visited_cols = [False] * N
    col_components = []
    for x in range(N):
        if not visited_cols[x]:
            q = deque()
            q.append(x)
            visited_cols[x] = True
            size = 0
            while q:
                node = q.popleft()
                size += 1
                for y in range(N):
                    if not visited_cols[y] and can_swap_cols(node, y):
                        visited_cols[y] = True
                        q.append(y)
            col_components.append(size)

    fact = [1] * (N + 1)
    for i in range(1, N + 1):
        fact[i] = fact[i-1] * i % MOD

    row_product = 1
    for s in row_components:
        row_product = row_product * fact[s] % MOD

    col_product = 1
    for s in col_components:
        col_product = col_product * fact[s] % MOD

    ans = (row_product * col_product) % MOD
    print(ans)

