    sorted_matches = []
    for i, j in matches:
        # k is position of j+1 in i's list
        k = opponent_map[i][j+1]
        # l is position of i+1 in j's list
        l = opponent_map[j][i+1]
        lower = max(k, l)
        sorted_matches.append((lower, i, j))

    # Sort by lower
    sorted_matches.sort()

    # Process each match in order
    day_sets = [set() for _ in range(N)]
    max_day = 0

    for lower, i, j in sorted_matches:
        # k is position of j+1 in i's list
        k = opponent_map[i][j+1]
        # l is position of i+1 in j's list
        l = opponent_map[j][i+1]
        # lower is max(k, l)
