    # Compute sum for x in [low, n]
    bits = list(map(int, bin(n)[2:].zfill(m)))
    from functools import lru_cache

    @lru_cache(maxsize=None)
    def dp(pos, tight, count):
        if pos == m:
            return 1 / (2 ** count)
        res = 0
        max_bit = bits[pos] if tight else 1
        for bit in [0, 1]:
            if bit > max_bit:
                continue
            new_tight = tight and (bit == max_bit)
            new_count = count + (bit == 1)
            res += dp(pos + 1, new_tight, new_count)
        return res

    # First bit is 1, so start at pos=1 with count=1 and tight=True
    digit_dp_result = dp(1, True, 1)
    total += digit_dp_result * (2 ** m)
    return total

def count_valid_r(x, U):
    if U < 0:
        return 0
    x_bin = bin(x)[2:]
    U_bin = bin(U)[2:]
    max_len = max(len(x_bin), len(U_bin))
    x_bin = x_bin.zfill(max_len)
    U_bin = U_bin.zfill(max_len)
    from functools import lru_cache

    @lru_cache(maxsize=None)
    def dp(pos, tight):
        if pos == max_len:
            return 1
        res = 0
        max_bit = int(U_bin[pos]) if tight else 1
        if x_bin[pos] == '1':
            # Must choose 0
            if 0 > max_bit:
                return 0
            new_tight = tight and (0 == max_bit)
            res += dp(pos + 1, new_tight)
        else:
            for bit in [0, 1]:
                if bit > max_bit:
                    continue
                new_tight = tight and (bit == max_bit)
                res += dp(pos + 1, new_tight)
        return res

    return dp(0, True)

def main():
    L, R = map(int, sys.stdin.readline().split())
    X_max = (R + 1) // 2
    part1 = 0
    if L <= X_max:
        part1 = (compute_S(X_max) - compute_S(L - 1)) % MOD
    part2 = 0
    for x in range(X_max + 1, R + 1):
        U = R - x
        cnt = count_valid_r(x, U)
        part2 = (part2 + cnt) % MOD
    total = (part1 + part2) % MOD
    print(total)

