        rows.append([int(c) for c in line])

    # Precompute prefix sums for each column
    prefix_sums = []
    for j in range(W):
        prefix = [0] * (H + 1)
        for i in range(H):
            prefix[i + 1] = prefix[i] + rows[i][j]
        prefix_sums.append(prefix)

    min_cuts = float('inf')

    # Try all possible horizontal divisions
    for m in range(H):  # m is the number of horizontal cuts (0 to H-1)
        # Generate all combinations of m cut positions
        for cuts in combinations(range(H - 1), m):
            # Determine the groups
            groups = []
            prev = 0
            for cut in sorted(cuts):
                groups.append((prev, cut))
                prev = cut + 1
            groups.append((prev, H - 1))
            num_groups = len(groups)
            # Compute sum_col_group for each group and column
            sum_col_group = []
            for g in range(num_groups):
                start_row, end_row = groups[g]
                col_sums = []
                for j in range(W):
                    total = prefix_sums[j][end_row + 1] - prefix_sums[j][start_row]
                    col_sums.append(total)
                sum_col_group.append(col_sums)
            # Now process columns to find vertical cuts
            current_sums = [0] * num_groups
            vertical_cuts = 0
            for j in range(W):
                # Add column j to current_sums
                for g in range(num_groups):
                    current_sums[g] += sum_col_group[g][j]
                # Check if any exceeds K
                if any(s > K for s in current_sums):
                    vertical_cuts += 1
                    current_sums = [0] * num_groups
            # total cuts is m (horizontal) + vertical_cuts
            total_cuts = m + vertical_cuts
            if total_cuts < min_cuts:
                min_cuts = total_cuts
    print(min_cuts)

