def main():
    input = sys.stdin.read
    data = input().split()
    N = int(data[0])
    K = int(data[1])
    S = data[2]

    def split_groups(s):
        groups = []
        n = len(s)
        i = 0
        while i < n:
            c = s[i]
            j = i
            while j < n and s[j] == c:
                j += 1
            groups.append((c, j - i))
            i = j
        return groups

    groups = split_groups(S)
    ones_groups = []
    zeros_between = []
    leading_zero = None
    trailing_zero = None

    for group in groups:
        if group[0] == '1':
            ones_groups.append(group[1])
        else:
            if leading_zero is None:
                leading_zero = group[1]
            else:
                zeros_between.append(group[1])

    if groups[-1][0] == '0':
        trailing_zero = groups[-1][1]
    else:
        trailing_zero = None

    if not ones_groups:
        print(N if K >= 1 else 0)
        return

    m = len(ones_groups)
    prefix_ones = [0] * (m + 1)
    for i in range(m):
        prefix_ones[i+1] = prefix_ones[i] + ones_groups[i]

    len_zeros_between = len(zeros_between)
    prefix_zeros = [0] * (len_zeros_between + 1)
    for i in range(len_zeros_between):
        prefix_zeros[i+1] = prefix_zeros[i] + zeros_between[i]

    max_total = 0

    for i in range(m):
        j_max = min(i + K, m - 1)
        for j in range(i, j_max + 1):
            num_zeros_between = j - i
            remaining_flips = K - num_zeros_between
            sum_ones = prefix_ones[j+1] - prefix_ones[i]
            sum_zeros_between = prefix_zeros[j] - prefix_zeros[i] if j - i > 0 else 0
            total_window = sum_ones + sum_zeros_between
            additional = 0
            if remaining_flips >= 1:
                if leading_zero is not None:
                    additional = max(additional, leading_zero)
                if trailing_zero is not None:
                    additional = max(additional, trailing_zero)
            if remaining_flips >= 2:
                if leading_zero is not None and trailing_zero is not None:
                    additional += leading_zero + trailing_zero
            total = total_window + additional
            if total > max_total:
                max_total = total

    print(max_total)

