def main():
    import sys
    from collections import defaultdict

    N = int(sys.stdin.readline())
    if N == 0:
        print(1)
        return

    # Map characters to integers: A=0, C=1, G=2, T=3
    # Forbidden patterns: (0,1,2), (1,0,2), (0,2,1)

    def is_forbidden(s):
        return s == (0, 1, 2) or s == (1, 0, 2) or s == (0, 2, 1)

    # Initialize DP
    dp = defaultdict(int)
    if N == 1:
        for c in range(4):
            dp[(c,)] = 1
    elif N == 2:
        for a in range(4):
            for b in range(4):
                dp[(a, b)] = 1
    else:
        # For N >= 3, start with all possible pairs
        dp = defaultdict(int)
        for a in range(4):
            for b in range(4):
                dp[(a, b)] = 1

    for _ in range(N - 2):
        new_dp = defaultdict(int)
        for state in dp:
            state_len = len(state)
            if state_len == 2:
                a, b = state
                for c in range(4):
                    # new state is (a, b, c)
                    # check the three possible swaps in the new string a, b, c
                    if is_forbidden((a, b, c)) or is_forbidden((b, a, c)) or is_forbidden((a, c, b)):
                        continue
                    new_state = (a, b, c)
                    new_dp[new_state] = (new_dp[new_state] + dp[state]) % MOD
            elif state_len == 3:
                a, b, c = state
                for d in range(4):
                    # new state is (b, c, d)
                    # check the six possible substrings after swaps
                    sub1 = (b, a, c)
                    sub2 = (a, c, d)
                    sub3 = (a, c, b)
                    sub4 = (c, b, d)
                    sub5 = (a, b, d)
                    sub6 = (b, d, c)
                    if any(is_forbidden(sub) for sub in [sub1, sub2, sub3, sub4, sub5, sub6]):
                        continue
                    new_state = (b, c, d)
                    new_dp[new_state] = (new_dp[new_state] + dp[state]) % MOD
        dp = new_dp

    # Sum all possible states for the final dp
    total = sum(dp.values()) % MOD
    print(total)

