    input = sys.stdin.read
    data = input().split()
    N = int(data[0])
    s = list(map(int, data[1:N+1]))

    max_score = -float('inf')

    # Check for m=0
    A = N - 1
    if 0 <= A < N:
        current_score = s[A]
        if current_score > max_score:
            max_score = current_score

    # Check for m from 1 to 200
    for m in range(1, 201):
        for A in range(1, N):
            numerator = (m + 1) * A - (N - 1)
            if numerator <= 0:
                continue
            if numerator % m != 0:
                continue
            B = numerator // m
            if B <= 0:
                continue

            positions = set()
            current_sum = 0
            valid = True

            for s_step in range(1, 2 * m + 1):
                additions = (s_step + 1) // 2
                subtractions = s_step // 2
                x = additions * A - subtractions * B
                if x < 0 or x >= N:
                    valid = False
                    break
                if x in positions:
                    valid = False
                    break
                positions.add(x)
                current_sum += s[x]

            if valid:
                if current_sum > max_score:
                    max_score = current_sum

    print(max_score)

