def main():
    import sys
    input = sys.stdin.read
    data = input().split()
    N = int(data[0])
    s = list(map(int, data[1:N+1]))

    pre_sum_even = defaultdict(list)
    pre_sum_odd = defaultdict(list)

    for t in range(1, N+1):
        # Precompute even sums
        pre_even = [0]
        current_sum = 0
        for i in range(1, N//t + 1):
            x = i * t
            if x >= N:
                break
            current_sum += s[x]
            pre_even.append(current_sum)
        pre_sum_even[t] = pre_even

        # Precompute odd sums
        pre_odd = [0]
        current_sum = 0
        for j in range(0, N):
            x = N-1 - t * j
            if x < 0 or x >= N:
                break
            current_sum += s[x]
            pre_odd.append(current_sum)
        pre_sum_odd[t] = pre_odd

    max_score = s[-1]  # k=1 case

    # Try k from 2 to 200
    for k in range(2, 200):
        t_max = (N-1) // (k-1)
        for t in range(0, t_max + 1):
            if t >= (N-1) // k + 1:
                continue
            B = N-1 - t * k
            if B <= 0:
                continue
            # Check for sum_odd
            if t not in pre_sum_odd or k > len(pre_sum_odd[t]):
                continue
            sum_odd = pre_sum_odd[t][k]
            # Check for sum_even
            if t not in pre_sum_even or k-1 > len(pre_sum_even[t])-1:
                continue
            sum_even = pre_sum_even[t][k-1]
            total = sum_odd + sum_even
            if total > max_score:
                max_score = total

    print(max_score)

