    max_score = -10**100

    def get_divisors(n):
        divisors = set()
        for i in range(1, int(n**0.5) + 1):
            if n % i == 0:
                divisors.add(i)
                divisors.add(n // i)
        return divisors

    if N >= 3:
        # Case 1: even steps
        divisors = get_divisors(N-1)
        for m in divisors:
            d = (N-1) // m
            max_B = N-1 - d
            if max_B < 1:
                continue
            for B in range(1, max_B + 1):
                A = B + d
                current = 0
                score = 0
                valid = True
                while True:
                    new_pos = current + A
                    if new_pos == N-1:
                        break
                    elif new_pos < 0 or new_pos >= N:
                        valid = False
                        break
                    score += s[new_pos]
                    current = new_pos
                    new_pos = current - B
                    if new_pos == N-1:
                        break
                    elif new_pos < 0 or new_pos >= N:
                        valid = False
                        break
                    score += s[new_pos]
                    current = new_pos
                if valid and new_pos == N-1:
                    if score > max_score:
                        max_score = score

        # Case 2: odd steps
        for m in range(1, N):
            r = (N-1) % m
            A_min = (N-1) // (m + 1) + 1
            A_max = N - 1
            if r >= A_min:
                first_A = r
            else:
                delta = A_min - r
                k = (delta + m - 1) // m
                first_A = r + k * m
            if first_A > A_max:
                continue
            last_A = A_max - ((A_max - r) % m)
            if last_A < r:
                continue
            for A in range(first_A, last_A + 1, m):
                numerator = (m + 1) * A - (N - 1)
                if numerator % m != 0:
                    continue
                B = numerator // m
                if B <= 0:
                    continue
                current = 0
                score = 0
                valid = True
                while True:
                    new_pos = current + A
