    total = 1
    for i in range(1, n):
        curr_or = defaultdict(int)
        curr_or[a[i]] += 1
        for or_val in prev_or:
            if (or_val & a[i]) == 0:
                new_or = or_val | a[i]
                curr_or[new_or] += prev_or[or_val]
        total += sum(curr_or.values())
        prev_or = curr_or
    print(total)

