from math import gcd
from collections import defaultdict

def main():
    input = sys.stdin.read().split()
    N = int(input[0])
    A = list(map(int, input[1:N+1]))

    # Compute overall GCD
    current_gcd = A[0]
    for num in A[1:]:
        current_gcd = math.gcd(current_gcd, num)
        if current_gcd == 1:
            break
    if current_gcd != 1:
        print("not coprime")
        return

    # Precompute smallest prime factors (SPF)
    max_num = 10**6
    spf = list(range(max_num + 1))
    for i in range(2, int(math.isqrt(max_num)) + 1):
        if spf[i] == i:  # i is a prime
            for j in range(i * i, max_num + 1, i):
                if spf[j] == j:
                    spf[j] = i

    # Function to get unique prime factors of a number
    def get_primes(x):
        primes = set()
        while x > 1:
            p = spf[x]
            primes.add(p)
            while x % p == 0:
                x //= p
        return primes

    # Check pairwise coprimality
    freq = defaultdict(int)
    for num in A:
        if num == 1:
            continue
        primes = get_primes(num)
        for p in primes:
            freq[p] += 1

    has_duplicate = any(v >= 2 for v in freq.values())
    if has_duplicate:
        print("setwise coprime")
    else:
        print("pairwise coprime")

