from math import gcd
from collections import defaultdict

def main():
    input = sys.stdin.read().split()
    N = int(input[0])
    A = list(map(int, input[1:N+1]))

    max_val = 10**6
    spf = list(range(max_val + 1))
    for i in range(2, int(math.isqrt(max_val)) + 1):
        if spf[i] == i:
            for j in range(i*i, max_val + 1, i):
                if spf[j] == j:
                    spf[j] = i

    current_gcd = A[0]
    for num in A[1:]:
        current_gcd = math.gcd(current_gcd, num)
        if current_gcd == 1:
            break

    if current_gcd != 1:
        print("not coprime")
        return

    primes_count = defaultdict(int)
    for num in A:
        if num == 1:
            continue
        temp = num
        primes = set()
        while temp != 1:
            p = spf[temp]
            primes.add(p)
            while temp % p == 0:
                temp //= p
        for p in primes:
            primes_count[p] += 1

    pairwise = True
    for count in primes_count.values():
        if count >= 2:
            pairwise = False
            break

    if pairwise:
        print("pairwise coprime")
    else:
        print("setwise coprime")

