            group_D_y.append(y)
        else:
            group_RL_y.append(y)

    # Compute max and min for x groups
    maxR_x = max(group_R_x) if group_R_x else -float('inf')
    minR_x = min(group_R_x) if group_R_x else float('inf')
    maxL_x = max(group_L_x) if group_L_x else -float('inf')
