import bisect

def main():
    input = sys.stdin.read
    data = input().split()
    idx = 0
    R = int(data[idx]); idx +=1
    C = int(data[idx]); idx +=1
    K = int(data[idx]); idx +=1

    items = [[] for _ in range(R+1)]  # 1-based
    for _ in range(K):
        r = int(data[idx]); idx +=1
        c = int(data[idx]); idx +=1
        v = int(data[idx]); idx +=1
        items[r].append( (c, v) )

    # Preprocess each row's items
    row_sorted_columns = [[] for _ in range(R+1)]
    row_column_to_value = [{} for _ in range(R+1)]
    row_prefix_sums = [ [ [0]*4 for _ in range(C+1) ] for _ in range(R+1) ]  # row_prefix_sums[i][j][k]

    for i in range(1, R+1):
        sorted_items = sorted(items[i], key=lambda x: x[0])
        sorted_columns = [c for (c, v) in sorted_items]
        row_sorted_columns[i] = sorted_columns
        for (c, v) in sorted_items:
            row_column_to_value[i][c] = v
        # Compute prefix sums
        values = [v for (c, v) in sorted_items]
        values.sort(reverse=True)
        prefix = [0] * (len(values)+1)
        for k in range(len(values)):
            prefix[k+1] = prefix[k] + values[k]
        # For each column j in 1..C, find the number of items up to j
        for j in range(1, C+1):
            m = bisect.bisect_right(sorted_columns, j)
            for k in range(4):
                if k <= m:
                    row_prefix_sums[i][j][k] = prefix[k]
                else:
                    row_prefix_sums[i][j][k] = -float('inf')

    # Initialize prev_dp for the previous row
    prev_dp = [ -float('inf') ] * (C+1)
    prev_dp[1] = 0  # start at (1,1)

    for i in range(1, R+1):
        current_dp_prev = [ -float('inf') ] * 4
        for j in range(1, C+1):
            new_dp = [ -float('inf') ] * 4
            # from_left: previous column in the same row
            if j > 1:
                for k in range(4):
                    # from previous column
                    if current_dp_prev[k] != -float('inf'):
                        # do not collect item
                        if new_dp[k] < current_dp_prev[k]:
                            new_dp[k] = current_dp_prev[k]
                        # collect item if possible
                        has_item = False
                        pos = bisect.bisect_left(row_sorted_columns[i], j)
                        if pos < len(row_sorted_columns[i]) and row_sorted_columns[i][pos] == j:
                            has_item = True
                        if has_item:
                            val = row_column_to_value[i][j]
                            if k >= 1:
                                if new_dp[k] < current_dp_prev[k-1] + val:
                                    new_dp[k] = current_dp_prev[k-1] + val
            # from_above: previous row's column j
            if i > 1:
                for k in range(4):
                    val = prev_dp[j] + row_prefix_sums[i][j][k]
                    if new_dp[k] < val:
                        new_dp[k] = val
            current_dp_prev = new_dp
        # Update prev_dp for the next row
        prev_dp = [ -float('inf') ] * (C+1)
        for j in range(1, C+1):
            for k in range(4):
                if current_dp_prev[k] != -float('inf'):
                    if prev_dp[j] < current_dp_prev[k]:
                        prev_dp[j] = current_dp_prev[k]

    # The answer is the maximum value in the last row's current_dp_prev
    print(max(current_dp_prev))

