                if not reversed_flag:
                    d.appendleft(C_i)
                else:
                    d.append(C_i)
            else:
                if not reversed_flag:
                    d.append(C_i)
                else:
                    d.appendleft(C_i)
    if reversed_flag:
        print(''.join(reversed(d)))
    else:
        print(''.join(d))

