import sys

def main():
    input = sys.stdin.read().split()
    ptr = 0
    N = int(input[ptr])
    ptr += 1
    S = list(map(int, input[ptr:ptr+N]))
    ptr += N
    T = list(map(int, input[ptr:ptr+N]))
    ptr += N
    U = list(map(int, input[ptr:ptr+N]))
    ptr += N
    V = list(map(int, input[ptr:ptr+N]))
    ptr += N

    matrix = [[0]*N for _ in range(N)]

    for k in range(64):
        R = [None]*N
        C = [None]*N
        for i in range(N):
            if S[i] == 0:
                if (U[i] >> k) & 1:
                    R[i] = 'all_1'
                else:
                    R[i] = 'at_least_0'
            else:
                if (U[i] >> k) & 1:
                    R[i] = 'at_least_1'
                else:
                    R[i] = 'all_0'
        for j in range(N):
            if T[j] == 0:
                if (V[j] >> k) & 1:
                    C[j] = 'all_1'
                else:
                    C[j] = 'at_least_0'
            else:
                if (V[j] >> k) & 1:
                    C[j] = 'at_least_1'
                else:
                    C[j] = 'all_0'

        has_all_1_row = any(r == 'all_1' for r in R)
        has_all_0_col = any(c == 'all_0' for c in C)
        if has_all_1_row and has_all_0_col:
            print(-1)
            return

        has_all_0_row = any(r == 'all_0' for r in R)
